const data = $input.first().json;

return [
  {
    json: {
      product_name: data.product_name || "",
      product_idea: data.product_idea || "",
      business_problem: data.business_problem || "",
      target_users: data.target_users || "",
      business_goal: data.business_goal || "",
      main_features: data.main_features || "",
      platform: data.platform || "",
      priority: data.priority || "",
      timeline: data.timeline || "",
      additional_requirements: data.additional_requirements || "",
      submitted_at: new Date().toISOString()
    }
  }
];

let raw = $json.output;

if (!raw) {
  throw new Error("Final PRD Generator returned no output.");
}

raw = String(raw).trim();

// Remove Markdown code fences if the model accidentally adds them
raw = raw
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let prd;

try {
  prd = JSON.parse(raw);
} catch (error) {

  // Attempt to extract the JSON object
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");

  if (start === -1 || end === -1) {
    throw new Error(
      "Final PRD Generator did not return valid JSON."
    );
  }

  const jsonText = raw.substring(start, end + 1);

  try {
    prd = JSON.parse(jsonText);
  } catch (secondError) {
    throw new Error(
      "Unable to parse Final PRD Generator output."
    );
  }
}

return [
  {
    json: prd
  }
];
